function cleanGeneratedLabel(value){if(typeof value!=='string')return value;return value.replace(/^\s*(?:(?:\[(?:DOX\s*더미|더미|샘플)\]|(?:DOX\s*더미|더미|샘플)(?:\s*[:：-]\s*|\s+))\s*)+/i,'').replace(/\s*\((?:DOX\s*더미|더미|샘플)\)\s*$/i,'');}
function normalizeGeneratedLabels(record){if(!record)return;for(const key of ['title','owner'])if(typeof record[key]==='string')record[key]=cleanGeneratedLabel(record[key]);for(const key of ['project_name','supplier_name','ordering_contact'])if(record.values&&typeof record.values[key]==='string')record.values[key]=cleanGeneratedLabel(record.values[key]);}
const SCHEMA=[
 ['사업명','project_name','project',true],['발주기관','ordering_organization','project'],['발주부서','ordering_department','project'],['발주담당자','ordering_contact','project'],['발주담당자 연락처','ordering_phone','project'],['발주담당자 이메일','ordering_email','project'],['수행장소','delivery_location','project',true],['입찰방식','bidding_method','project',true],
 ['공급업체','supplier_name','supplier',true],['공급업체 사업자등록번호','supplier_business_number','supplier'],['공급업체 대표자','supplier_representative','supplier'],['공급업체 연락처','supplier_phone','supplier'],['공급업체 담당자','supplier_contact','supplier'],
 ['입찰공고번호','bid_notice_number','documents'],['낙찰통지서 번호','award_notice_number','documents'],['계약서 번호','contract_number','documents'],['발주번호','purchase_order_number','documents'],['검수서 번호','inspection_number','documents'],['세금계산서 승인번호','tax_invoice_number','documents'],['거래명세서 번호','transaction_statement_number','documents'],
 ['총액(VAT 포함)','total_amount','settlement',true,'number'],['공급가액','supply_amount','settlement',false,'number'],['부가가치세','vat_amount','settlement',false,'number'],['검수일','inspection_date','settlement',true,'date'],['주요 산출물','deliverables','settlement',true,'textarea'],['수행제안 요약','proposal_summary','settlement',true,'textarea']
].map(([label,key,group,full,type])=>({label,key,group,full:!!full,type:type||'text'}));
const GROUPS={project:'사업·발주 정보',supplier:'공급업체',documents:'증빙서류',settlement:'정산·검수'};
function numeric(v){const t=String(v??'').replace(/[,₩원\s]/g,'');return t!==''&&Number.isFinite(Number(t))?Number(t):null;}
function asDate(v){if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:'';}const s=String(v??'').trim();const m=s.match(/^(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})\.?$/);return m?`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`:s;}
function initialValue(f,r){if(f.type==='date')return asDate(r?.value);if(f.type==='number'){const n=numeric(r?.value);return n===null?String(r?.value??''):String(n);}return String(r?.value??'');}
function parseWorkbook(wb,filename){for(const name of wb.SheetNames){const sheet=wb.Sheets[name];if(!sheet['!ref'])continue;const range=XLSX.utils.decode_range(sheet['!ref']);if(range.e.r>10000||range.e.c>100)continue;const grid=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true,range:0});const hi=grid.findIndex(row=>['항목','내용','확인'].every(l=>row.some(v=>String(v).trim()===l)));if(hi<0)continue;const headers=grid[hi].map(v=>String(v).trim()),cols=['항목','내용','확인'].map(l=>headers.indexOf(l));const rows=grid.slice(hi+1).map((r,i)=>({label:String(r[cols[0]]??'').trim(),value:r[cols[1]]??'',status:String(r[cols[2]]??'').trim(),sourceRow:hi+i+2})).filter(r=>r.label);const labels=rows.map(r=>r.label),missing=SCHEMA.filter(f=>!labels.includes(f.label));if(missing.length)throw new Error('필수 항목 누락: '+missing.slice(0,3).map(f=>f.label).join(', '));if(new Set(labels).size!==labels.length)throw new Error('중복된 항목명이 있습니다. 항목별로 한 행만 남겨 주세요.');return {filename,sheet:name,rows,importedAt:new Date().toISOString(),mode:'upload'};}throw new Error('항목 · 내용 · 확인 열이 있는 시트를 찾지 못했습니다.');}
